"""Small data types exchanged between modules."""
from __future__ import annotations

from dataclasses import dataclass
from typing import Optional, Tuple

LEFT = "left"
RIGHT = "right"

Point = Tuple[float, float]


@dataclass
class ClickEvent:
    """A click generated by the remote (or the mouse in simulation mode)."""
    button: str            # LEFT | RIGHT
    pos: Point             # board coordinates where the click happens
    source: str = "remote"


@dataclass
class PointerSample:
    """Result of one pointer-tracking step.

    board : smoothed position in board (projected-screen) pixels, None if unknown
    cam   : smoothed position in camera pixels, None if nothing was ever seen
    tracked : True when the dot was seen in THIS frame
    lost_frames : consecutive frames without detection
    """
    board: Optional[Point] = None
    cam: Optional[Point] = None
    tracked: bool = False
    lost_frames: int = 0

    @property
    def usable(self) -> bool:
        return self.board is not None
